+//! Properties are invariants checked after every tick and at the
+//! end of the run.
+
+use crate::state_machine::{Accumulator, Op};
+use anyhow::{ensure, Result};
+use std::collections::HashSet;
+use std::sync::Arc;
+use vsr_rs::Replica;
+
+/// Read-only view of the simulated system handed to properties.
+pub struct SimContext<'a> {
+    pub tick: u64,
+    pub replicas: &'a [Replica<Accumulator>],
+    pub state_machines: &'a [Arc<Accumulator>],
+    /// Responses the client has received, in order.
+    pub responses: &'a [i64],
+    /// ID of the primary of replica 0's current view.
+    pub primary_id: usize,
+}
+
+pub trait Property {
+    fn name(&self) -> &'static str;
+
+    /// Called after every tick.
+    fn check(&mut self, ctx: &SimContext) -> Result<()>;
+
+    /// Called once at the end of the run, after the network has been drained
+    /// with faults disabled.
+    fn finalize(&mut self, _ctx: &SimContext) -> Result<()> {
+        Ok(())
+    }
+}
+
+/// The default property set.
+pub fn default_properties() -> Vec<Box<dyn Property>> {
+    vec![
+        Box::new(CommitNumberMonotonic::default()),
+        Box::new(StateMatchesCommittedLog::default()),
+        Box::new(CommittedPrefixAgreement::default()),
+        Box::new(NoDuplicateOps::default()),
+        Box::new(ResponsesMatchCommits::default()),
+        Box::new(Convergence),
+    ]
+}
+
+/// A replica's commit number never decreases and never exceeds its op number,
+/// and its op number always equals its log length.
+#[derive(Default)]
+pub struct CommitNumberMonotonic {
+    last_commit: Vec<usize>,
+}
+
+impl Property for CommitNumberMonotonic {
+    fn name(&self) -> &'static str {
+        "commit-number-monotonic"
+    }
+
+    fn check(&mut self, ctx: &SimContext) -> Result<()> {
+        self.last_commit.resize(ctx.replicas.len(), 0);
+        for (id, replica) in ctx.replicas.iter().enumerate() {
+            let commit = replica.commit_number();
+            let op = replica.op_number();
+            let len = replica.log().len();
+            ensure!(
+                op == len,
+                "tick {}: replica {id} op_number {op} != log length {len}",
+                ctx.tick
+            );
+            ensure!(
+                commit <= op,
+                "tick {}: replica {id} commit_number {commit} > op_number {op}",
+                ctx.tick
+            );
+            ensure!(
+                commit >= self.last_commit[id],
+                "tick {}: replica {id} commit_number went backwards: {} -> {commit}",
+                ctx.tick,
+                self.last_commit[id]
+            );
+            self.last_commit[id] = commit;
+        }
+        Ok(())
+    }
+}
+
+/// A replica's state machine has applied exactly the committed prefix of its
+/// log, in order, and its value is the fold of those operations.
+#[derive(Default)]
+pub struct StateMatchesCommittedLog {
+    /// Per replica: (number of committed entries already verified, expected value).
+    verified: Vec<(usize, i64)>,
+}
+
+impl Property for StateMatchesCommittedLog {
+    fn name(&self) -> &'static str {
+        "state-matches-committed-log"
+    }
+
+    fn check(&mut self, ctx: &SimContext) -> Result<()> {
+        self.verified.resize(ctx.replicas.len(), (0, 0));
+        for (id, (replica, sm)) in ctx.replicas.iter().zip(ctx.state_machines).enumerate() {
+            let commit = replica.commit_number();
+            let log = replica.log();
+            let (verified, value) = &mut self.verified[id];
+            sm.with_state(|state| {
+                ensure!(
+                    state.applied.len() == commit,
+                    "tick {}: replica {id} applied {} ops but commit_number is {commit}",
+                    ctx.tick,
+                    state.applied.len()
+                );
+                for i in *verified..commit {
+                    ensure!(
+                        state.applied[i] == log[i],
+                        "tick {}: replica {id} applied {:?} at index {i} but log has {:?}",
+                        ctx.tick,
+                        state.applied[i],
+                        log[i]
+                    );
+                    *value = log[i].kind.apply(*value);
+                }
+                *verified = commit;
+                ensure!(
+                    state.value == *value,
+                    "tick {}: replica {id} value {} != expected {value}",
+                    ctx.tick,
+                    state.value
+                );
+                Ok(())
+            })?;
+        }
+        Ok(())
+    }
+}
+
+/// All replicas agree on the committed prefix of the log: if two replicas
+/// have both committed index `i`, they hold the same operation there.
+#[derive(Default)]
+pub struct CommittedPrefixAgreement {
+    /// The union of all committed prefixes seen so far.
+    canonical: Vec<Op>,
+    /// Per replica: number of committed entries already verified.
+    verified: Vec<usize>,
+}
+
+impl Property for CommittedPrefixAgreement {
+    fn name(&self) -> &'static str {
+        "committed-prefix-agreement"
+    }
+
+    fn check(&mut self, ctx: &SimContext) -> Result<()> {
+        self.verified.resize(ctx.replicas.len(), 0);
+        for (id, replica) in ctx.replicas.iter().enumerate() {
+            let commit = replica.commit_number();
+            let log = replica.log();
+            for i in self.verified[id]..commit {
+                if let Some(canonical) = self.canonical.get(i) {
+                    ensure!(
+                        *canonical == log[i],
+                        "tick {}: replica {id} committed {:?} at index {i} but another replica committed {canonical:?}",
+                        ctx.tick,
+                        log[i]
+                    );
+                } else {
+                    self.canonical.push(log[i].clone());
+                }
+            }
+            self.verified[id] = commit;
+        }
+        Ok(())
+    }
+}
+
+/// No operation appears twice in any replica's log.
+#[derive(Default)]
+pub struct NoDuplicateOps {
+    /// Per replica: (log entries already verified, IDs seen).
+    seen: Vec<(usize, HashSet<u64>)>,
+}
+
+impl Property for NoDuplicateOps {
+    fn name(&self) -> &'static str {
+        "no-duplicate-ops"
+    }
+
+    fn check(&mut self, ctx: &SimContext) -> Result<()> {
+        self.seen
+            .resize_with(ctx.replicas.len(), || (0, HashSet::new()));
+        for (id, replica) in ctx.replicas.iter().enumerate() {
+            let log = replica.log();
+            let (verified, seen) = &mut self.seen[id];
+            for (i, op) in log.iter().enumerate().skip(*verified) {
+                ensure!(
+                    seen.insert(op.id),
+                    "tick {}: replica {id} has duplicate op {op:?} at index {i}",
+                    ctx.tick
+                );
+            }
+            *verified = log.len();
+        }
+        Ok(())
+    }
+}
+
+/// The client receives exactly one response per committed operation, and each
+/// response carries the accumulator value after that operation.
+#[derive(Default)]
+pub struct ResponsesMatchCommits {
+    verified: usize,
+    value: i64,
+}
+
+impl Property for ResponsesMatchCommits {
+    fn name(&self) -> &'static str {
+        "responses-match-commits"
+    }
+
+    fn check(&mut self, ctx: &SimContext) -> Result<()> {
+        let primary = &ctx.replicas[ctx.primary_id];
+        let commit = primary.commit_number();
+        ensure!(
+            ctx.responses.len() == commit,
+            "tick {}: client got {} responses but primary commit_number is {commit}",
+            ctx.tick,
+            ctx.responses.len()
+        );
+        let log = primary.log();
+        for i in self.verified..ctx.responses.len() {
+            self.value = log[i].kind.apply(self.value);
+            ensure!(
+                ctx.responses[i] == self.value,
+                "tick {}: response {i} is {} but expected {}",
+                ctx.tick,
+                ctx.responses[i],
+                self.value
+            );
+        }
+        self.verified = ctx.responses.len();
+        Ok(())
+    }
+}
+
+/// Once the network is drained, every replica has the same log, has committed
+/// all of it, and holds the same state machine value.
+pub struct Convergence;
+
+impl Property for Convergence {
+    fn name(&self) -> &'static str {
+        "convergence"
+    }
+
+    fn check(&mut self, _ctx: &SimContext) -> Result<()> {
+        Ok(())
+    }
+
+    fn finalize(&mut self, ctx: &SimContext) -> Result<()> {
+        let primary = &ctx.replicas[ctx.primary_id];
+        let primary_log = primary.log();
+        let primary_value = ctx.state_machines[ctx.primary_id].value();
+        for (id, (replica, sm)) in ctx.replicas.iter().zip(ctx.state_machines).enumerate() {
+            let log = replica.log();
+            ensure!(
+                log.len() == primary_log.len(),
+                "replica {id} log length {} != primary log length {}",
+                log.len(),
+                primary_log.len()
+            );
+            ensure!(
+                *log == *primary_log,
+                "replica {id} log differs from primary log"
+            );
+            ensure!(
+                replica.commit_number() == log.len(),
+                "replica {id} committed {} of {} log entries",
+                replica.commit_number(),
+                log.len()
+            );
+            ensure!(
+                sm.value() == primary_value,
+                "replica {id} value {} != primary value {primary_value}",
+                sm.value()
+            );
+        }
+        Ok(())
+    }
+}

